+        << "sinks numel " << arg_sinks.numel() << " < 128 heads with enable_sink";
+  }
+  check_dtype(arg_output, DLDataType{kDLBfloat, 16, 1}, "output");
+  TVM_FFI_CHECK(arg_output.numel() == (int64_t)num_rows * 128 * 512, ValueError)
+      << "output numel " << arg_output.numel() << " != expected " << (int64_t)num_rows * 128 * 512;
+  check_cuda_tensor(arg_ws_partial_output, "partial_output");
+  check_dtype(arg_ws_partial_output, DLDataType{kDLBfloat, 16, 1}, "partial_output");
+  TVM_FFI_CHECK(arg_ws_partial_output.numel() == (int64_t)((num_rows) * (int64_t)(128) * (num_split) * (512)), ValueError)
+      << "workspace 'partial_output' numel " << arg_ws_partial_output.numel()
+      << " != expected " << (int64_t)((num_rows) * (int64_t)(128) * (num_split) * (512));
+  check_cuda_tensor(arg_ws_partial_lse, "partial_lse");
+  check_dtype(arg_ws_partial_lse, DLDataType{kDLFloat, 32, 1}, "partial_lse");
+  TVM_FFI_CHECK(arg_ws_partial_lse.numel() == (int64_t)((num_rows) * (int64_t)(128) * (num_split)), ValueError)
+      << "workspace 'partial_lse' numel " << arg_ws_partial_lse.numel()
+      << " != expected " << (int64_t)((num_rows) * (int64_t)(128) * (num_split));
+  {
+    // The mainloop never applies the sink or bmm2_scale (partial scale 1, sink off); the reducer does.
+    int64_t gx = grid_x;
+    int64_t gy = 1;
+    int64_t gz = 1;
+    CAKE_PROGRAM_SHIM::CAKE_VARIANT_NS_0::Run(arg_q_rows, arg_kv_half_pages, arg_kv_half_pages, arg_kv_half_pages, arg_ws_partial_output, arg_ws_partial_lse, arg_seq_lens, arg_block_tables, arg_sinks, softmax_scale_log2, 1.0, num_split, total_work_items, table_width, 0, q_len, page_shift, gx, gy, gz, stream);
+  }
+  {
+    int64_t gx = num_rows;
+    int64_t gy = 128;
+    int64_t gz = 1;
+    CAKE_PROGRAM_SHIM::CAKE_VARIANT_NS_1::Run(arg_ws_partial_output, arg_ws_partial_lse, arg_output, arg_sinks, 128, num_split, bmm2_scale, enable_sink, gx, gy, gz, stream);
+  }
+}
